import{_ as r,o as t,c as a,ag as n}from"./chunks/framework.D1K3FKSn.js";const g=JSON.parse('{"title":"References & Background","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kilnrender.com/reference/references.html"}],["meta",{"property":"og:title","content":"References & Background | Kiln"}],["meta",{"property":"og:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}],["meta",{"property":"og:url","content":"https://kilnrender.com/reference/references.html"}],["meta",{"name":"twitter:title","content":"References & Background | Kiln"}],["meta",{"name":"twitter:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}]]},"headers":[],"relativePath":"reference/references.md","filePath":"reference/references.md"}'),i={name:"reference/references.md"};function s(o,e,l,c,p,m){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="references-background" tabindex="-1">References &amp; Background <a class="header-anchor" href="#references-background" aria-label="Permalink to &quot;References &amp; Background&quot;">​</a></h1><p>Kiln is an implementation-focused project that builds on well-established ideas in volume rendering, sparse streaming, and real-time graphics. It adapts proven techniques to a modern WebGPU context.</p><h2 id="academic-technical-references" tabindex="-1">Academic &amp; technical references <a class="header-anchor" href="#academic-technical-references" aria-label="Permalink to &quot;Academic &amp; technical references&quot;">​</a></h2><p>The following works were particularly influential during development:</p><ul><li><p><strong>Barrett, S. (2008).</strong> <em>Sparse Virtual Textures</em>. Game Developers Conference (GDC) 2008. <a href="http://silverspaceship.com/src/svt/" target="_blank" rel="noreferrer">http://silverspaceship.com/src/svt/</a></p></li><li><p><strong>CesiumGS. (2019).</strong> <em>3D Tiles: Specification for Streaming Massive Heterogeneous 3D Geospatial Datasets</em>. Open Geospatial Consortium (OGC) Community Standard. <a href="https://github.com/CesiumGS/3d-tiles" target="_blank" rel="noreferrer">https://github.com/CesiumGS/3d-tiles</a></p></li><li><p><strong>Engel, K., Hadwiger, M., Kniss, J., Rezk-Salama, C., &amp; Weiskopf, D. (2006).</strong> <em>Real-Time Volume Graphics</em>. A K Peters/CRC Press. <a href="https://doi.org/10.1201/b10629" target="_blank" rel="noreferrer">https://doi.org/10.1201/b10629</a></p></li><li><p><strong>Karis, B. (2014).</strong> <em>High Quality Temporal Supersampling</em>. ACM SIGGRAPH 2014, Advances in Real-Time Rendering in Games. <a href="https://de45xmedrsdbp.cloudfront.net/Resources/files/TemporalAA_small-59732822.pdf" target="_blank" rel="noreferrer">https://de45xmedrsdbp.cloudfront.net/Resources/files/TemporalAA_small-59732822.pdf</a></p></li><li><p><strong>Levoy, M. (1990).</strong> <em>Efficient ray tracing of volume data</em>. ACM Transactions on Graphics, 9(3), 245–261. <a href="https://doi.org/10.1145/78964.78965" target="_blank" rel="noreferrer">https://doi.org/10.1145/78964.78965</a></p></li><li><p><strong>Lux, C., &amp; Fröhlich, B. (2009).</strong> <em>GPU-Based Ray Casting of Multiple Multi-resolution Volume Datasets</em>. In: Bebis, G., et al. Advances in Visual Computing. ISVC 2009. <a href="https://link.springer.com/chapter/10.1007/978-3-642-10520-3_10" target="_blank" rel="noreferrer">https://link.springer.com/chapter/10.1007/978-3-642-10520-3_10</a></p></li><li><p><strong>Maitin-Shepard, J., et al. (2021).</strong> <em>Neuroglancer: Web-based volumetric data visualization</em>. <a href="https://github.com/google/neuroglancer" target="_blank" rel="noreferrer">https://github.com/google/neuroglancer</a></p></li><li><p><strong>Moore, J., et al. (2023).</strong> <em>OME-Zarr: a cloud-optimized bioimaging file format with international community support</em>. Histochemistry and Cell Biology, 160(3), 223–251. <a href="https://doi.org/10.1007/s00418-023-02209-1" target="_blank" rel="noreferrer">https://doi.org/10.1007/s00418-023-02209-1</a></p></li><li><p><strong>Schütz, M. (2016).</strong> <em>Potree: Rendering Large Point Clouds in Web Browsers</em> [Master&#39;s thesis, Technische Universität Wien]. <a href="https://www.cg.tuwien.ac.at/research/publications/2016/SCHUETZ-2016-POT/" target="_blank" rel="noreferrer">https://www.cg.tuwien.ac.at/research/publications/2016/SCHUETZ-2016-POT/</a></p></li><li><p><strong>W3C GPU for the Web Working Group. (2026).</strong> <em>WebGPU</em>. W3C Candidate Recommendation Draft. <a href="https://gpuweb.github.io/gpuweb/" target="_blank" rel="noreferrer">https://gpuweb.github.io/gpuweb/</a></p></li><li><p><strong>IDR. (2024).</strong> <em>OME-NGFF Samples Directory</em>. Image Data Resource. <a href="https://idr.github.io/ome-ngff-samples/" target="_blank" rel="noreferrer">https://idr.github.io/ome-ngff-samples/</a></p></li></ul><h2 id="dataset-credits" tabindex="-1">Dataset credits <a class="header-anchor" href="#dataset-credits" aria-label="Permalink to &quot;Dataset credits&quot;">​</a></h2><p>Dataset attributions live alongside the demos in the <a href="/gallery.html#dataset-credits">Gallery</a>.</p>',7)])])}const h=r(i,[["render",s]]);export{g as __pageData,h as default};
